(() => {
  const additions=[{"id":"Butterfly","name":"pec deck machine fly","name_ua":"Зведення рук у тренажері «метелик»","aliases":["pec deck machine fly","Зведення рук у тренажері «метелик»"],"motion":{"src":"./assets/motion/0051.mp4","poster":"./assets/motion/0051.jpg","sourceId":"0051"},"muscleGroup":"chest","trackingType":"strength","equipment":"machine","primaryMuscles":["chest"],"secondaryMuscles":["shoulders"],"instructions":["Sit on the pec deck machine and adjust the seat so your arms are parallel to the floor.","Place your forearms against the arm pads or grip the handles with elbows bent at 90 degrees.","Press the arm pads together in front of your chest by contracting your pectoral muscles.","Pause at the peak of the contraction and squeeze your chest.","Slowly allow the arm pads to return to the starting position and repeat for the desired number of repetitions."]},{"id":"Svend_Press","name":"svend press chest","name_ua":"Жим Свенда","aliases":["svend press chest","Жим Свенда"],"motion":{"src":"./assets/motion/0052.mp4","poster":"./assets/motion/0052.jpg","sourceId":"0052"},"muscleGroup":"chest","trackingType":"strength","equipment":"body weight","primaryMuscles":["chest"],"secondaryMuscles":["shoulders","triceps"],"instructions":["Stand upright and hold a pair of weight plates pressed together at chest level with both palms.","Press the plates outward from your chest until your arms are nearly fully extended.","Squeeze the plates together throughout the entire movement to engage the inner chest.","Slowly pull the plates back towards your chest in a controlled manner.","Repeat for the desired number of repetitions."]},{"id":"motion-0053","name":"air bike sprint","name_ua":"Спринт на Air Bike","aliases":["air bike sprint","Спринт на Air Bike"],"motion":{"src":"./assets/motion/0053.mp4","poster":"./assets/motion/0053.jpg","sourceId":"0053"},"muscleGroup":"cardio","trackingType":"time","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["hamstrings","abdominals","shoulders"],"instructions":["Sit on the air bike and adjust the seat so your legs are slightly bent at full extension.","Grip the moving handles with both hands.","Begin pedaling and pumping the handles simultaneously at maximum effort.","Sprint at full intensity for the desired interval duration.","Slow down gradually and rest before repeating."]},{"id":"Barbell_Squat","name":"barbell back squat","name_ua":"Присідання зі штангою","aliases":["barbell back squat","Присідання зі штангою"],"motion":{"src":"./assets/motion/0054.mp4","poster":"./assets/motion/0054.jpg","sourceId":"0054"},"muscleGroup":"legs","trackingType":"strength","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings","lower back"],"instructions":["Position a barbell on your upper traps and step back from the rack with feet shoulder-width apart.","Point your toes slightly outward and keep your chest up and core braced.","Descend by bending your knees and pushing your hips back until your thighs are parallel to the floor.","Drive through your heels to extend your knees and hips and return to the standing position.","Repeat for the desired number of repetitions."]},{"id":"One_Leg_Barbell_Squat","name":"barbell bulgarian split squat","name_ua":"Болгарські присідання зі штангою","aliases":["barbell bulgarian split squat","Болгарські присідання зі штангою"],"motion":{"src":"./assets/motion/0055.mp4","poster":"./assets/motion/0055.jpg","sourceId":"0055"},"muscleGroup":"legs","trackingType":"strength","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings","lower back"],"instructions":["Stand in front of a bench and hold a barbell across your upper traps.","Extend one leg behind you and rest the top of your foot on the bench.","Lower your back knee toward the floor by bending your front knee, keeping your torso upright.","Descend until your front thigh is parallel to the floor.","Drive through your front heel to return to the starting position and repeat, then switch legs."]},{"id":"Front_Barbell_Squat","name":"barbell front squat","name_ua":"Фронтальні присідання","aliases":["barbell front squat","Фронтальні присідання"],"motion":{"src":"./assets/motion/0056.mp4","poster":"./assets/motion/0056.jpg","sourceId":"0056"},"muscleGroup":"legs","trackingType":"strength","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","abdominals","hamstrings"],"instructions":["Position a barbell in a front rack across the front of your shoulders with your elbows raised high.","Stand with feet shoulder-width apart and toes slightly pointed out.","Keeping your elbows high and torso upright, descend by bending your knees and hips.","Lower until your thighs are parallel to the floor or below.","Drive through your heels to return to the standing position and repeat."]},{"id":"Barbell_Hip_Thrust","name":"barbell hip thrust","name_ua":"Ягодичний міст зі штангою","aliases":["barbell hip thrust","Ягодичний міст зі штангою"],"motion":{"src":"./assets/motion/0057.mp4","poster":"./assets/motion/0057.jpg","sourceId":"0057"},"muscleGroup":"legs","trackingType":"strength","equipment":"barbell","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","lower back","abdominals"],"instructions":["Sit on the floor with your upper back against a bench and a padded barbell across your hips.","Plant your feet flat on the floor hip-width apart with knees bent.","Drive through your heels to thrust your hips upward until your body forms a straight line from knees to shoulders.","Squeeze your glutes at the top of the movement.","Lower your hips back toward the floor in a controlled manner and repeat for the desired number of repetitions."]},{"id":"motion-0058","name":"barbell march","name_ua":"Марш зі штангою","aliases":["barbell march","Марш зі штангою"],"motion":{"src":"./assets/motion/0058.mp4","poster":"./assets/motion/0058.jpg","sourceId":"0058"},"muscleGroup":"legs","trackingType":"strength","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","abdominals","lower back"],"instructions":["Hold a barbell across your upper traps as in a back squat position with feet hip-width apart.","Brace your core and maintain an upright posture.","Lift one knee upward to hip height in a marching motion while keeping your stance foot flat.","Lower your foot and repeat the movement with the opposite leg.","Continue alternating legs in a controlled marching motion for the desired number of repetitions."]},{"id":"motion-0059","name":"barbell reverse lunges","name_ua":"Випади назад зі штангою","aliases":["barbell reverse lunges","Випади назад зі штангою"],"motion":{"src":"./assets/motion/0059.mp4","poster":"./assets/motion/0059.jpg","sourceId":"0059"},"muscleGroup":"legs","trackingType":"strength","equipment":"barbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings","abdominals"],"instructions":["Stand upright with a barbell across your upper traps and feet together.","Step one foot directly backward and lower your back knee toward the floor.","Continue descending until your front thigh is parallel to the floor.","Push through your front heel to bring your back foot forward to the starting position.","Alternate legs for the desired number of repetitions."]},{"id":"Romanian_Deadlift","name":"barbell romanian deadlift","name_ua":"Румунська тяга","aliases":["barbell romanian deadlift","Румунська тяга"],"motion":{"src":"./assets/motion/0060.mp4","poster":"./assets/motion/0060.jpg","sourceId":"0060"},"muscleGroup":"legs","trackingType":"strength","equipment":"barbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back"],"instructions":["Stand with feet hip-width apart holding a barbell in front of your thighs with an overhand grip.","Keep a soft bend in your knees and your back flat throughout the movement.","Hinge at the hips and push them back as you lower the bar along your legs.","Continue lowering until you feel a deep stretch in your hamstrings.","Drive your hips forward to return to the upright position and repeat for the desired number of repetitions."]},{"id":"One-Legged_Cable_Kickback","name":"cable leg kickback","name_ua":"Відведення ноги назад у кросовері","aliases":["cable leg kickback","Відведення ноги назад у кросовері"],"motion":{"src":"./assets/motion/0061.mp4","poster":"./assets/motion/0061.jpg","sourceId":"0061"},"muscleGroup":"legs","trackingType":"strength","equipment":"cable","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","lower back"],"instructions":["Attach an ankle strap to the low pulley of a cable machine and secure it to one ankle.","Face the machine and hold the frame for support, keeping your body slightly inclined.","Keeping your knee straight, kick your strapped leg backward and upward as far as possible.","Squeeze your glute at the top of the movement.","Slowly return your leg to the starting position and repeat, then switch legs."]},{"id":"Bicycling_Stationary","name":"cycling","name_ua":"Велотренажер","aliases":["cycling","Велотренажер"],"motion":{"src":"./assets/motion/0062.mp4","poster":"./assets/motion/0062.jpg","sourceId":"0062"},"muscleGroup":"cardio","trackingType":"time","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["hamstrings","lower legs","glutes"],"instructions":["Mount a stationary bike and adjust the seat height so your leg has a slight bend at full pedal extension.","Place your feet in the pedal straps and grip the handlebars.","Begin pedaling at a comfortable cadence, maintaining an upright or forward-leaning posture.","Adjust the resistance as needed to reach your target intensity level.","Continue for the desired duration, then gradually slow to a cool down pace."]},{"id":"motion-0063","name":"dumbbell bulgarian split squat","name_ua":"Болгарські присідання з гантелями","aliases":["dumbbell bulgarian split squat","Болгарські присідання з гантелями"],"motion":{"src":"./assets/motion/0063.mp4","poster":"./assets/motion/0063.jpg","sourceId":"0063"},"muscleGroup":"legs","trackingType":"strength","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Stand in front of a bench and hold a dumbbell in each hand at your sides.","Extend one leg back and rest the top of your foot on the bench.","Lower your back knee toward the floor by bending your front knee.","Descend until your front thigh is parallel to the floor.","Drive through your front heel to return to the starting position and repeat, then switch legs."]},{"id":"Goblet_Squat","name":"dumbbell goblet squat","name_ua":"Гоблет-присідання","aliases":["dumbbell goblet squat","Гоблет-присідання"],"motion":{"src":"./assets/motion/0064.mp4","poster":"./assets/motion/0064.jpg","sourceId":"0064"},"muscleGroup":"legs","trackingType":"strength","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","abdominals"],"instructions":["Stand with feet shoulder-width apart holding a dumbbell vertically at chest level with both hands cupping the top end.","Keep your elbows tucked in and your chest up.","Descend into a squat by bending your knees and pushing your hips back until your thighs are parallel to the floor.","Drive through your heels to return to the standing position.","Repeat for the desired number of repetitions."]},{"id":"motion-0065","name":"dumbbell hip hinge","name_ua":"Нахили з гантелями (hip hinge)","aliases":["dumbbell hip hinge","Нахили з гантелями (hip hinge)"],"motion":{"src":"./assets/motion/0065.mp4","poster":"./assets/motion/0065.jpg","sourceId":"0065"},"muscleGroup":"legs","trackingType":"strength","equipment":"dumbbell","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back"],"instructions":["Stand with feet hip-width apart holding a dumbbell in each hand at your sides.","Keep a slight bend in your knees and your back flat throughout the movement.","Hinge at the hips and push them back as you lower your torso toward the floor.","Lower until you feel a stretch in your hamstrings, then drive your hips forward to return to standing.","Repeat for the desired number of repetitions."]},{"id":"motion-0066","name":"dumbbell jump squat","name_ua":"Присідання зі стрибком і гантелями","aliases":["dumbbell jump squat","Присідання зі стрибком і гантелями"],"motion":{"src":"./assets/motion/0066.mp4","poster":"./assets/motion/0066.jpg","sourceId":"0066"},"muscleGroup":"legs","trackingType":"strength","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings","lower legs"],"instructions":["Stand with feet shoulder-width apart holding a light dumbbell in each hand at your sides.","Perform a squat by bending your knees and pushing your hips back to thigh-parallel depth.","Explosively drive through your heels to jump off the ground as high as possible.","Land softly with bent knees to absorb the impact.","Immediately descend into the next squat and repeat for the desired number of repetitions."]},{"id":"Elliptical_Trainer","name":"elliptical hiit machine","name_ua":"Еліптичний тренажер","aliases":["elliptical hiit machine","Еліптичний тренажер"],"motion":{"src":"./assets/motion/0067.mp4","poster":"./assets/motion/0067.jpg","sourceId":"0067"},"muscleGroup":"cardio","trackingType":"time","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["hamstrings","lower legs","shoulders"],"instructions":["Step onto the elliptical machine and grip the moving handles.","Set a high resistance level appropriate for interval training.","Push and pull the handles while driving through the pedals at maximum effort for the work interval.","Reduce your pace to a slow recovery stride for the rest interval.","Continue alternating between work and rest intervals for the desired duration."]},{"id":"Hack_Squat","name":"hack squat machine","name_ua":"Гак-присідання в тренажері","aliases":["hack squat machine","Гак-присідання в тренажері"],"motion":{"src":"./assets/motion/0068.mp4","poster":"./assets/motion/0068.jpg","sourceId":"0068"},"muscleGroup":"legs","trackingType":"strength","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Position yourself on the hack squat machine with your back against the pad and shoulders under the shoulder pads.","Place your feet shoulder-width apart on the platform with toes slightly pointed out.","Release the safety handles and lower the sled by bending your knees to 90 degrees or below.","Drive through your heels to extend your knees and return to the starting position.","Repeat for the desired number of repetitions."]},{"id":"Thigh_Abductor","name":"hip abduction machine","name_ua":"Розведення ніг у тренажері","aliases":["hip abduction machine","Розведення ніг у тренажері"],"motion":{"src":"./assets/motion/0069.mp4","poster":"./assets/motion/0069.jpg","sourceId":"0069"},"muscleGroup":"legs","trackingType":"strength","equipment":"machine","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings"],"instructions":["Sit on the hip abduction machine with your outer thighs resting against the padded levers.","Adjust the starting position so your legs are together and feet are flat on the foot rests.","Push your legs outward against the resistance by abducting your hips as far as comfortable.","Pause at the end of the range of motion, then slowly return your legs to the starting position.","Repeat for the desired number of repetitions."]},{"id":"motion-0070","name":"kettlebell hold march","name_ua":"Марш із гирею","aliases":["kettlebell hold march","Марш із гирею"],"motion":{"src":"./assets/motion/0070.mp4","poster":"./assets/motion/0070.jpg","sourceId":"0070"},"muscleGroup":"legs","trackingType":"strength","equipment":"kettlebells","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","abdominals","lower back"],"instructions":["Stand upright holding a kettlebell in each hand at your sides.","Brace your core and maintain an upright posture with shoulders back.","Lift one knee upward to hip height in a controlled marching motion.","Lower that foot to the floor and immediately lift the opposite knee.","Continue alternating legs in a slow, deliberate march for the desired number of repetitions."]},{"id":"motion-0071","name":"kettlebell lift up","name_ua":"Піднімання гирі з підлоги","aliases":["kettlebell lift up","Піднімання гирі з підлоги"],"motion":{"src":"./assets/motion/0071.mp4","poster":"./assets/motion/0071.jpg","sourceId":"0071"},"muscleGroup":"legs","trackingType":"strength","equipment":"kettlebells","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","lower back","shoulders"],"instructions":["Stand with feet hip-width apart and a kettlebell on the floor between your feet.","Hinge at the hips and bend your knees to grip the kettlebell handle with both hands.","Brace your core and maintain a flat back as you prepare to lift.","Drive through your heels and extend your hips and knees to stand upright, lifting the kettlebell.","Lower the kettlebell back to the floor in a controlled manner and repeat."]},{"id":"motion-0072","name":"kettlebell swing","name_ua":"Махи гирею двома руками","aliases":["kettlebell swing","Махи гирею двома руками"],"motion":{"src":"./assets/motion/0072.mp4","poster":"./assets/motion/0072.jpg","sourceId":"0072"},"muscleGroup":"legs","trackingType":"strength","equipment":"kettlebells","primaryMuscles":["glutes"],"secondaryMuscles":["hamstrings","lower back","shoulders"],"instructions":["Stand with feet slightly wider than shoulder-width and the kettlebell on the floor in front of you.","Hinge at the hips to grip the kettlebell with both hands and hike it back between your legs.","Explosively drive your hips forward to propel the kettlebell upward to chest or shoulder height.","Allow the kettlebell to swing back down and hike it back between your legs, hinging at the hips.","Repeat the swing in a fluid, continuous motion for the desired number of repetitions."]},{"id":"Leg_Extensions","name":"leg extension machine","name_ua":"Розгинання ніг у тренажері","aliases":["leg extension machine","Розгинання ніг у тренажері"],"motion":{"src":"./assets/motion/0073.mp4","poster":"./assets/motion/0073.jpg","sourceId":"0073"},"muscleGroup":"legs","trackingType":"strength","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"instructions":["Sit on the leg extension machine and adjust the back pad so your knees align with the machine's pivot point.","Place your shins behind the padded lever and grip the handles at your sides.","Extend your legs upward by straightening your knees until your legs are parallel to the floor.","Pause at the top and squeeze your quadriceps.","Slowly lower the lever back to the starting position and repeat for the desired number of repetitions."]},{"id":"Leg_Press","name":"leg press machine","name_ua":"Жим ногами","aliases":["leg press machine","Жим ногами"],"motion":{"src":"./assets/motion/0074.mp4","poster":"./assets/motion/0074.jpg","sourceId":"0074"},"muscleGroup":"legs","trackingType":"strength","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Sit on the leg press machine and place your feet shoulder-width apart on the platform.","Release the safety handles and lower the platform by bending your knees toward your chest.","Stop when your knees reach approximately 90 degrees or your lower back begins to lift off the seat.","Drive through your heels to extend your knees and push the platform back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"Lying_Leg_Curls","name":"lying leg curl machine","name_ua":"Згинання ніг лежачи","aliases":["lying leg curl machine","Згинання ніг лежачи"],"motion":{"src":"./assets/motion/0075.mp4","poster":"./assets/motion/0075.jpg","sourceId":"0075"},"muscleGroup":"legs","trackingType":"strength","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["lower legs","glutes"],"instructions":["Lie face down on the leg curl machine and position the pad just above your heels.","Grip the handles beneath the bench for stability.","Curl your heels toward your glutes by bending your knees as far as the machine allows.","Pause at the top and squeeze your hamstrings.","Slowly lower your legs back to the starting position and repeat for the desired number of repetitions."]},{"id":"Battling_Ropes","name":"rope wave","name_ua":"Хвилі канатами","aliases":["rope wave","Хвилі канатами"],"motion":{"src":"./assets/motion/0076.mp4","poster":"./assets/motion/0076.jpg","sourceId":"0076"},"muscleGroup":"cardio","trackingType":"time","equipment":"body weight","primaryMuscles":["shoulders"],"secondaryMuscles":["upper arms","abdominals","hamstrings"],"instructions":["Hold one end of a battle rope in each hand and stand in a half-squat position.","Brace your core and keep your feet shoulder-width apart.","Rapidly raise and lower one arm while the other arm descends, creating alternating waves in the rope.","Maintain a continuous, powerful wave motion for the desired interval duration.","Rest and repeat for the desired number of sets."]},{"id":"Rowing_Stationary","name":"rowing machine","name_ua":"Гребний тренажер","aliases":["rowing machine","Гребний тренажер"],"motion":{"src":"./assets/motion/0077.mp4","poster":"./assets/motion/0077.jpg","sourceId":"0077"},"muscleGroup":"cardio","trackingType":"time","equipment":"machine","primaryMuscles":["middle back"],"secondaryMuscles":["hamstrings","shoulders","abdominals"],"instructions":["Sit on the rowing machine, secure your feet in the straps, and grip the handle with both hands.","Begin with your knees bent, leaning slightly forward, and arms extended.","Drive through your legs to extend your knees while simultaneously leaning back slightly.","As your legs reach full extension, pull the handle toward your lower chest by bending your elbows.","Reverse the sequence to return to the starting position and repeat for the desired duration."]},{"id":"Running_Treadmill","name":"run on treadmill","name_ua":"Бігова доріжка","aliases":["run on treadmill","Бігова доріжка"],"motion":{"src":"./assets/motion/0078.mp4","poster":"./assets/motion/0078.jpg","sourceId":"0078"},"muscleGroup":"cardio","trackingType":"time","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["hamstrings","lower legs","glutes"],"instructions":["Step onto the treadmill and set your desired speed and incline level.","Begin walking and gradually increase the speed to your running pace.","Maintain an upright posture with a slight forward lean and land softly on your midfoot.","Swing your arms in coordination with your legs to maintain rhythm.","Continue running for the desired duration, then gradually decrease speed to a walking cool down."]},{"id":"Seated_Leg_Curl","name":"seated leg curl machine","name_ua":"Згинання ніг сидячи","aliases":["seated leg curl machine","Згинання ніг сидячи"],"motion":{"src":"./assets/motion/0079.mp4","poster":"./assets/motion/0079.jpg","sourceId":"0079"},"muscleGroup":"legs","trackingType":"strength","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["lower legs","glutes"],"instructions":["Sit on the seated leg curl machine and adjust the back pad so your knees align with the pivot point.","Place your legs over the top pad and secure the lower pad just above your ankles.","Curl your legs downward by bending your knees as far as the machine allows.","Pause at the bottom and squeeze your hamstrings.","Slowly return your legs to the starting position and repeat for the desired number of repetitions."]},{"id":"Leverage_Shoulder_Press","name":"seated overhead press","name_ua":"Жим плечима в тренажері","aliases":["seated overhead press","Жим плечима в тренажері"],"motion":{"src":"./assets/motion/0080.mp4","poster":"./assets/motion/0080.jpg","sourceId":"0080"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps","traps"],"instructions":["Sit on a shoulder press machine and adjust the seat so the handles are at shoulder height.","Grip the handles with both hands and plant your feet flat on the floor.","Press the handles upward until your arms are fully extended overhead.","Pause briefly at the top, then slowly lower the handles back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"Dumbbell_Step_Ups","name":"step-ups (weighted)","name_ua":"Зашагування на платформу з гантелями","aliases":["step-ups (weighted)","Зашагування на платформу з гантелями"],"motion":{"src":"./assets/motion/0081.mp4","poster":"./assets/motion/0081.jpg","sourceId":"0081"},"muscleGroup":"legs","trackingType":"strength","equipment":"dumbbell","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","hamstrings"],"instructions":["Stand in front of a box or bench holding a dumbbell in each hand at your sides.","Step one foot up onto the surface and drive through that heel to lift your body up.","Bring your back foot up to stand fully on the box.","Step the leading foot back down to the floor followed by the trailing foot.","Alternate the leading leg or complete all repetitions on one side before switching."]},{"id":"motion-0082","name":"stepmill machine version 1","name_ua":"Кроки на сходовому тренажері (варіант 1)","aliases":["stepmill machine version 1","Кроки на сходовому тренажері (варіант 1)"],"motion":{"src":"./assets/motion/0082.mp4","poster":"./assets/motion/0082.jpg","sourceId":"0082"},"muscleGroup":"cardio","trackingType":"time","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","lower legs","hamstrings"],"instructions":["Step onto the stepmill machine and grip the handrails lightly for balance.","Set your desired speed on the control panel.","Begin stepping at a comfortable pace, placing your full foot on each step.","Drive through your heel with each step to engage your glutes and quads.","Continue for the desired duration, maintaining an upright posture and minimizing reliance on the handrails."]},{"id":"Step_Mill","name":"stepmill machine","name_ua":"Сходовий тренажер","aliases":["stepmill machine","Сходовий тренажер"],"motion":{"src":"./assets/motion/0083.mp4","poster":"./assets/motion/0083.jpg","sourceId":"0083"},"muscleGroup":"cardio","trackingType":"time","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["glutes","lower legs","hamstrings"],"instructions":["Mount the stepmill and set your target speed and duration.","Step onto the rotating staircase and begin climbing at a steady pace.","Keep your torso upright and engage your core throughout the exercise.","Drive through each step using your full foot to activate the glutes and quads.","Complete the session for the desired duration, then slow down to cool off before dismounting."]},{"id":"motion-0084","name":"stiff-legged deadlift machine","name_ua":"Тяга на прямих ногах у тренажері","aliases":["stiff-legged deadlift machine","Тяга на прямих ногах у тренажері"],"motion":{"src":"./assets/motion/0084.mp4","poster":"./assets/motion/0084.jpg","sourceId":"0084"},"muscleGroup":"legs","trackingType":"strength","equipment":"machine","primaryMuscles":["hamstrings"],"secondaryMuscles":["glutes","lower back"],"instructions":["Stand on the platform of a deadlift machine with feet hip-width apart and grip the handles.","Keep your legs nearly straight with a slight bend in your knees.","Hinge at the hips and lower the handles along your legs until you feel a deep hamstring stretch.","Drive your hips forward to return to the upright starting position.","Repeat for the desired number of repetitions."]},{"id":"Triceps_Pushdown_-_Rope_Attachment","name":"triceps pushdown (cable - rope)","name_ua":"Розгинання на трицепс (канат)","aliases":["triceps pushdown (cable - rope)","Розгинання на трицепс (канат)"],"motion":{"src":"./assets/motion/0085.mp4","poster":"./assets/motion/0085.jpg","sourceId":"0085"},"muscleGroup":"arms","trackingType":"strength","equipment":"cable","primaryMuscles":["triceps"],"secondaryMuscles":["lower arms"],"instructions":["Attach a rope handle to the high pulley of a cable machine and stand facing the machine.","Grasp the rope with both hands using a neutral grip and tuck your elbows close to your sides.","Push the rope downward by extending your arms until they are fully straight.","At the bottom, spread the rope ends apart slightly to maximize tricep contraction.","Slowly allow the rope to rise back to the starting position and repeat for the desired number of repetitions."]},{"id":"Walking_Treadmill","name":"walk on treadmill","name_ua":"Ходьба на доріжці","aliases":["walk on treadmill","Ходьба на доріжці"],"motion":{"src":"./assets/motion/0086.mp4","poster":"./assets/motion/0086.jpg","sourceId":"0086"},"muscleGroup":"cardio","trackingType":"time","equipment":"machine","primaryMuscles":["quadriceps"],"secondaryMuscles":["hamstrings","lower legs","glutes"],"instructions":["Step onto the treadmill and set a comfortable walking speed and incline.","Begin walking at your chosen pace, maintaining an upright posture.","Swing your arms naturally in coordination with your stride.","Keep your gaze forward and avoid looking down at your feet.","Continue walking for the desired duration, then gradually bring the belt to a stop."]},{"id":"Arnold_Dumbbell_Press","name":"arnold press dumbbell","name_ua":"Жим Арнольда","aliases":["arnold press dumbbell","Жим Арнольда"],"motion":{"src":"./assets/motion/0087.mp4","poster":"./assets/motion/0087.jpg","sourceId":"0087"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps","traps","upper arms"],"instructions":["Sit on a bench with back support and hold a dumbbell in each hand at chest height, palms facing you.","Begin the press by rotating your palms to face forward as you push the dumbbells upward.","Continue pressing until your arms are fully extended overhead.","Reverse the motion, rotating your palms back to face you as you lower the dumbbells to chest height.","Repeat for the desired number of repetitions."]},{"id":"Barbell_Shoulder_Press","name":"barbell overhead press standing","name_ua":"Жим над головою","aliases":["barbell overhead press standing","Жим над головою"],"motion":{"src":"./assets/motion/0088.mp4","poster":"./assets/motion/0088.jpg","sourceId":"0088"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps","traps","abdominals"],"instructions":["Stand with feet shoulder-width apart and hold a barbell at shoulder height with an overhand grip.","Brace your core and maintain a neutral spine throughout the movement.","Press the barbell directly overhead until your arms are fully extended.","Pause at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"Upright_Barbell_Row","name":"barbell upright row","name_ua":"Тяга штанги до підборіддя","aliases":["barbell upright row","Тяга штанги до підборіддя"],"motion":{"src":"./assets/motion/0089.mp4","poster":"./assets/motion/0089.jpg","sourceId":"0089"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"barbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps","biceps"],"instructions":["Stand upright holding a barbell with an overhand grip, hands approximately shoulder-width apart.","Let the bar hang in front of your thighs with your arms extended.","Pull the bar upward along your body by raising your elbows above the level of your hands.","Continue pulling until the bar reaches chin height and your elbows are above your shoulders.","Slowly lower the bar back to the starting position and repeat for the desired number of repetitions."]},{"id":"Standing_Dumbbell_Press","name":"dumbbell overhead standard","name_ua":"Жим гантелей стоячи","aliases":["dumbbell overhead standard","Жим гантелей стоячи"],"motion":{"src":"./assets/motion/0090.mp4","poster":"./assets/motion/0090.jpg","sourceId":"0090"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps","traps"],"instructions":["Stand with feet shoulder-width apart and hold a dumbbell in each hand at shoulder height, palms facing forward.","Brace your core and maintain an upright posture.","Press the dumbbells upward until your arms are fully extended overhead.","Pause briefly at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},{"id":"Standing_Dumbbell_Upright_Row","name":"dumbbell upright row","name_ua":"Тяга гантелей до підборіддя","aliases":["dumbbell upright row","Тяга гантелей до підборіддя"],"motion":{"src":"./assets/motion/0091.mp4","poster":"./assets/motion/0091.jpg","sourceId":"0091"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps","biceps"],"instructions":["Stand upright holding a dumbbell in each hand with a neutral grip in front of your thighs.","Pull the dumbbells upward along your body by raising your elbows above the level of your hands.","Continue pulling until the dumbbells reach chest height and your elbows are at shoulder level.","Pause at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"Front_Dumbbell_Raise","name":"front raise (dumbbell)","name_ua":"Підйом гантелей перед собою","aliases":["front raise (dumbbell)","Підйом гантелей перед собою"],"motion":{"src":"./assets/motion/0092.mp4","poster":"./assets/motion/0092.jpg","sourceId":"0092"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["chest","traps"],"instructions":["Stand upright holding a dumbbell in each hand in front of your thighs with palms facing your body.","Keep a slight bend in your elbows and your back straight.","Raise one or both dumbbells forward and upward until your arms are parallel to the floor.","Pause briefly at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"Front_Plate_Raise","name":"front raise (weighted plate)","name_ua":"Підйом диска перед собою","aliases":["front raise (weighted plate)","Підйом диска перед собою"],"motion":{"src":"./assets/motion/0093.mp4","poster":"./assets/motion/0093.jpg","sourceId":"0093"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"body weight","primaryMuscles":["shoulders"],"secondaryMuscles":["chest","traps"],"instructions":["Stand upright and hold a weight plate with both hands at the 3 and 9 o'clock positions in front of your thighs.","Keep a slight bend in your elbows and your core engaged.","Raise the plate forward and upward in a controlled arc until your arms are parallel to the floor.","Pause briefly at the top, then slowly lower the plate back to the starting position.","Repeat for the desired number of repetitions."]},{"id":"motion-0094","name":"kettlebell overhead press","name_ua":"Жим гирі над головою","aliases":["kettlebell overhead press","Жим гирі над головою"],"motion":{"src":"./assets/motion/0094.mp4","poster":"./assets/motion/0094.jpg","sourceId":"0094"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"kettlebells","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps","traps","abdominals"],"instructions":["Stand with feet shoulder-width apart and hold a kettlebell in one hand at shoulder height in the rack position.","Brace your core and keep your elbow pointing forward.","Press the kettlebell straight overhead until your arm is fully extended.","Pause at the top, then slowly lower the kettlebell back to the rack position.","Repeat for the desired number of repetitions, then switch arms."]},{"id":"motion-0095","name":"cable cross lateral raise","name_ua":"Перехресне розведення в кросовері","aliases":["cable cross lateral raise","Перехресне розведення в кросовері"],"motion":{"src":"./assets/motion/0095.mp4","poster":"./assets/motion/0095.jpg","sourceId":"0095"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["supraspinatus","upper traps"],"instructions":["Stand between two low cable pulleys and grasp the opposite handle with each hand so the cables cross in front of your body.","Stand upright with your feet shoulder-width apart, keep your core braced, and maintain a slight bend in your elbows.","Raise both arms out to your sides until they are approximately parallel to the floor.","Pause briefly at the top while squeezing your lateral deltoids.","Slowly lower the handles back to the starting position under control and repeat."]},{"id":"Side_Lateral_Raise","name":"lateral raises (dumbbell)","name_ua":"Розведення в сторони","aliases":["lateral raises (dumbbell)","Розведення в сторони"],"motion":{"src":"./assets/motion/0096.mp4","poster":"./assets/motion/0096.jpg","sourceId":"0096"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"dumbbell","primaryMuscles":["shoulders"],"secondaryMuscles":["traps"],"instructions":["Stand upright holding a dumbbell in each hand at your sides with a neutral grip.","Keep a slight bend in your elbows and your core engaged.","Raise both dumbbells out to the sides in a wide arc until your arms are parallel to the floor.","Pause briefly at the top and squeeze your medial delts.","Slowly lower the dumbbells back to the starting position and repeat for the desired number of repetitions."]},{"id":"motion-0097","name":"lateral raise machine","name_ua":"Розведення рук у тренажері","aliases":["lateral raise machine","Розведення рук у тренажері"],"motion":{"src":"./assets/motion/0097.mp4","poster":"./assets/motion/0097.jpg","sourceId":"0097"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":["upper traps","supraspinatus"],"instructions":["Stand on the platform of the lateral raise machine and position your upper arms against the pads.","Keep your chest up, core engaged, and maintain a slight bend in your elbows.","Raise the pads outward by abducting your shoulders until your upper arms are approximately parallel to the floor.","Pause briefly at the top and squeeze your lateral deltoids.","Slowly lower the weight back to the starting position under control and repeat."]},{"id":"Smith_Machine_Overhead_Shoulder_Press","name":"military press (seated - smith machine)","name_ua":"Жим сидячи в Сміті","aliases":["military press (seated - smith machine)","Жим сидячи в Сміті"],"motion":{"src":"./assets/motion/0098.mp4","poster":"./assets/motion/0098.jpg","sourceId":"0098"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":["triceps","traps"],"instructions":["Set a bench inside a smith machine and adjust the bar to shoulder height.","Sit on the bench and grip the bar with an overhand grip slightly wider than shoulder-width.","Unrack the bar and hold it at the front of your shoulders.","Press the bar upward until your arms are fully extended overhead.","Slowly lower the bar back to the starting position and repeat for the desired number of repetitions."]},{"id":"Reverse_Machine_Flyes","name":"rear delt fly (reverse pec deck)","name_ua":"Зворотні розведення в тренажері","aliases":["rear delt fly (reverse pec deck)","Зворотні розведення в тренажері"],"motion":{"src":"./assets/motion/0099.mp4","poster":"./assets/motion/0099.jpg","sourceId":"0099"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"machine","primaryMuscles":["shoulders"],"secondaryMuscles":["rhomboids","traps"],"instructions":["Sit facing the pec deck machine and adjust the seat so your arms are parallel to the floor.","Grip the handles with a neutral grip and keep a slight bend in your elbows.","Pull the handles outward and backward in a wide arcing motion by squeezing your rear delts and shoulder blades together.","Pause at the peak of the contraction.","Slowly return the handles to the starting position and repeat for the desired number of repetitions."]},{"id":"Cable_Rear_Delt_Fly","name":"rear delt cable fly","name_ua":"Зворотні розведення в кросовері","aliases":["rear delt cable fly","Зворотні розведення в кросовері"],"motion":{"src":"./assets/motion/0100.mp4","poster":"./assets/motion/0100.jpg","sourceId":"0100"},"muscleGroup":"shoulders","trackingType":"strength","equipment":"cable","primaryMuscles":["shoulders"],"secondaryMuscles":["rhomboids","middle traps"],"instructions":["Stand between two cable pulleys set at shoulder height.","Grasp the opposite cable handle with each hand and step back until there is tension on the cables.","Maintain a slight bend in your elbows and keep your chest up throughout the movement.","Pull your arms outward and backward in a wide arc until they are in line with your shoulders.","Squeeze your rear delts and upper back at the end of the movement.","Slowly return to the starting position under control and repeat."]}];
  const library=window.GYM_EXERCISE_LIBRARY || [];
  for(const item of additions){
    const existing=library.find(entry=>entry.id===item.id);
    if(existing){existing.motion=item.motion;existing.aliases=[...new Set([...existing.aliases,...item.aliases])];if(!existing.name_ua)existing.name_ua=item.name_ua;}
    else library.push({...item,images:[],localImages:true});
  }
  window.GYM_MOTION_POSTERS=additions.map(item=>item.motion.poster);
})();


